{
  "qa": [
    {
      "question": "上一季度物业经费主要用途有哪些？",
      "answer": "上一季度物业经费主要用于安装垃圾桶、维修损坏的摄像头、处理客户投诉赔偿损失等事项。"
    },
    {
      "question": "电梯设备故障如何处理？",
      "answer": "电梯设备故障时，物业会先检查是业主卡问题还是设备问题，若整栋楼反映卡不灵敏则更换设备，若仅个别住户问题则由该住户自行更换卡。"
    },
    {
      "question": "小区夜间巡逻安排及频次如何？",
      "answer": "小区夜间巡逻由保安负责，巡逻频次为每天晴天三次，具体时间从上午八点至中午十二点，分为上午班和中午班。"
    }
  ]
}
